scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "HNeon Universal HUB V2 | 2026",
   LoadingTitle = "HNeon Systems: Online",
   LoadingSubtitle = "Executing Advanced Payloads...",
   ConfigurationSaving = { Enabled = true, FolderName = "HNeon_Configs", FileName = "UniversalV2" }
})

-- [[ FE POWER SCRIPTS ]]
local Tab = Window:CreateTab("FE Scripts", 4483362458)

Tab:CreateButton({
   Name = "Infinite Yield (FE Admin)",
   Callback = function()
      loadstring(game:HttpGet('https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source'))()
   end,
})

Tab:CreateButton({
   Name = "Sypcer FE Hub (Keyless)",
   Callback = function()
      loadstring(game:HttpGet("https://raw.githubusercontent.com/yofriendfromschool1/Scripts/main/fe%20scripts.txt"))()
   end,
})

Tab:CreateButton({
   Name = "Tiger X Mobile Hub",
   Callback = function()
       -- Note: Most Tiger X versions are key-based, but this points to the master source
      loadstring(game:HttpGet("https://raw.githubusercontent.com/Xxtiger_xX/TigerX/main/Source.lua"))()
   end,
})

-- [[ REANIMATION TAB ]]
local ReanimTab = Window:CreateTab("Reanimation", 4483362458)

ReanimTab:CreateSection("Advanced Body Control")

ReanimTab:CreateButton({
   Name = "Krypton Reanimation (R6)",
   Callback = function()
      -- Krypton is the current top-tier reanimator for 2026. 
      -- Allows for custom client-sided rigs that server-side players can see.
      loadstring(game:HttpGet("https://raw.githubusercontent.com/KadeTheExploiter/Krypton/main/Module.luau"))()
      Rayfield:Notify({Title = "Krypton Loaded", Content = "R6 Character required for best results.", Duration = 5})
   end,
})

ReanimTab:CreateButton({
   Name = "Simple FE Reanimation V2",
   Callback = function()
      loadstring(game:HttpGet("https://pastebin.com/raw/HE0nReanim"))() -- Custom HNeon link placeholder
   end,
})

-- [[ MOVEMENT & COMBAT ]]
local Tab2 = Window:CreateTab("Combat/Movement", 4483362458)

Tab2:CreateSlider({
   Name = "WalkSpeed",
   Range = {16, 250},
   Increment = 1,
   CurrentValue = 16,
   Callback = function(Value)
      game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = Value
   end,
})

Tab2:CreateButton({
   Name = "FE Hitbox Extender (OP)",
   Callback = function()
      loadstring(game:HttpGet("https://raw.githubusercontent.com/puzis/Roblox/main/Hitbox.lua"))()
   end,
})

Rayfield:Notify({Title = "HNeon V2 Ready", Content = "Tiger X and Reanimation modules are hot.", Duration = 5})
